    public WarehouseService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new WarehouseEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(WarehouseRepository.class) );
		this.validator		= applicationContext.getBean(WarehouseValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Warehouse
	 */
		public Warehouse createWarehouse( CreateWarehouseCommand command ) {

		Warehouse entity = new Warehouse();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setWarehouseId( command.getWarehouseId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setAddress( command.getAddress() );
            entity.setTimeZone( command.getTimeZone() );
            entity.setAllowsOverAllocation( command.getAllowsOverAllocation() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Warehouse {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateWarehouseCommand
	 * @return		Warehouse
	 */
	public Warehouse updateWarehouse( UpdateWarehouseCommand command ) {

		Warehouse entity = new Warehouse();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setWarehouseId( command.getWarehouseId() );
            entity.setName( command.getName() );
            entity.setCode( command.getCode() );
            entity.setAddress( command.getAddress() );
            entity.setTimeZone( command.getTimeZone() );
            entity.setAllowsOverAllocation( command.getAllowsOverAllocation() );
            entity.setStorageLocations( command.getStorageLocations() );
            entity.setInventoryItems( command.getInventoryItems() );
            entity.setInboundShipments( command.getInboundShipments() );
            entity.setOutboundAllocations( command.getOutboundAllocations() );
            entity.setOriginTransfers( command.getOriginTransfers() );
            entity.setDestinationTransfers( command.getDestinationTransfers() );
            entity.setCycleCounts( command.getCycleCounts() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Warehouse {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteWarehouseCommand
	 */
	public void delete( DeleteWarehouseCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getWarehouseId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Warehouse {0} ", id );

	}

	/**
	 * Method to retrieve the Warehouse via WarehouseFetchOneSummary
	 * @param 	summary WarehouseFetchOneSummary
	 * @return 	WarehouseFetchOneResponse
	 */
	public Warehouse getWarehouse( WarehouseFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "WarehouseFetchOneSummary arg cannot be null" );

		Warehouse entity = null;
		UUID id = summary.getWarehouseId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Warehouse using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Warehouses
	 *
	 * @return 	List<Warehouse>
	 */
    public List<Warehouse> getAllWarehouse() {
		List<Warehouse> list = projector.findAll( new FindAllWarehouseQuery() );
		return list;
	}


